const NAME_CHAR = /[A-Za-z0-9_-]/

export function skipWS(line, pos) {
  while (pos < line.length && (line[pos] === ' ' || line[pos] === '\t')) pos++
  return pos
}

function isDelimiter(ch) {
  return ch === undefined || ch === ',' || ch === ']' || ch === '}' || ch === '#' || ch === ';'
}

export function parseBasicString(line, pos, lineNo) {
  // line[pos] === '"'
  pos++
  let out = ''
  while (true) {
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
    const ch = line[pos]
    if (ch === '"') {
      pos++
      return { value: out, pos }
    }
    if (ch === '\\') {
      pos++
      if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
      const esc = line[pos]
      switch (esc) {
        case '"':
          out += '"'
          pos++
          break
        case '\\':
          out += '\\'
          pos++
          break
        case 'n':
          out += '\n'
          pos++
          break
        case 't':
          out += '\t'
          pos++
          break
        case 'r':
          out += '\r'
          pos++
          break
        case '0':
          out += '\0'
          pos++
          break
        case 'u': {
          const hex = line.slice(pos + 1, pos + 5)
          if (hex.length < 4 || !/^[0-9A-Fa-f]{4}$/.test(hex)) {
            throw new ConfigError(lineNo, 'invalid escape \\u')
          }
          out += String.fromCharCode(parseInt(hex, 16))
          pos += 5
          break
        }
        default:
          throw new ConfigError(lineNo, `invalid escape \\${esc}`)
      }
      continue
    }
    out += ch
    pos++
  }
}

export function parseLiteralString(line, pos, lineNo) {
  // line[pos] === "'"
  pos++
  const start = pos
  while (true) {
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated string')
    if (line[pos] === "'") {
      const value = line.slice(start, pos)
      return { value, pos: pos + 1 }
    }
    pos++
  }
}

// Parses a dotted name starting at pos (may have leading whitespace already
// skipped by caller or not - this function skips it itself).
export function parseDottedName(line, pos, lineNo) {
  const segments = []
  while (true) {
    pos = skipWS(line, pos)
    const ch = line[pos]
    if (ch === '"') {
      const r = parseBasicString(line, pos, lineNo)
      segments.push(r.value)
      pos = r.pos
    } else if (ch === "'") {
      const r = parseLiteralString(line, pos, lineNo)
      segments.push(r.value)
      pos = r.pos
    } else if (ch !== undefined && NAME_CHAR.test(ch)) {
      const start = pos
      while (pos < line.length && NAME_CHAR.test(line[pos])) pos++
      segments.push(line.slice(start, pos))
    } else {
      throw new ConfigError(lineNo, 'expected a name')
    }
    pos = skipWS(line, pos)
    if (line[pos] === '.') {
      pos++
      continue
    }
    break
  }
  return { segments, pos }
