const FLOAT_RE = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*([eE][+-]?[0-9]+(_[0-9]+)*)?|[eE][+-]?[0-9]+(_[0-9]+)*)$/

function normalizeInteger(token) {
  let s = token.replace(/_/g, '')
  let sign = ''
  if (s[0] === '+' || s[0] === '-') {
    if (s[0] === '-') sign = '-'
    s = s.slice(1)
  }
  s = s.replace(/^0+(?=\d)/, '')
  if (/^0+$/.test(s)) return '0'
  return sign + s
}

function normalizeFloatNumber(token) {
  const s = token.replace(/_/g, '')
  return Number(s)
}

// Parses a value starting at pos. Returns { node, pos }.
export function parseValue(line, pos, lineNo) {
