  // line[pos] === '['
  pos++
  const items = []
  pos = skipWS(line, pos)
  if (line[pos] === ']') {
    return { node: { kind: 'array', items }, pos: pos + 1 }
  }
  while (true) {
    pos = skipWS(line, pos)
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated array')
    if (line[pos] === '#' || line[pos] === ';') throw new ConfigError(lineNo, 'unterminated array')
    const r = parseValue(line, pos, lineNo)
    items.push(r.node)
    pos = skipWS(line, r.pos)
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated array')
    const c = line[pos]
    if (c === '#' || c === ';') throw new ConfigError(lineNo, 'unterminated array')
    if (c === ',') {
      pos++
      pos = skipWS(line, pos)
      if (line[pos] === ']') {
        return { node: { kind: 'array', items }, pos: pos + 1 }
      }
      continue
    }
    if (c === ']') {
      return { node: { kind: 'array', items }, pos: pos + 1 }
    }
    throw new ConfigError(lineNo, 'unterminated array')
  }
}

function assignInto(tableNode, segments, valueNode, lineNo) {
  let node = tableNode
  const pathParts = []
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i]
    pathParts.push(seg)
    node = stepThrough(node, seg, pathParts.join('.'), lineNo)
  }
  const lastSeg = segments[segments.length - 1]
  pathParts.push(lastSeg)
  if (node.map.has(lastSeg)) {
    throw new ConfigError(lineNo, `key ${pathParts.join('.')} is defined twice`)
  }
  node.map.set(lastSeg, valueNode)
