    const existing = map.get(segment)
    if (existing.kind === 'table') return existing
    if (existing.kind === 'arrayOfTables') return existing.items[existing.items.length - 1]
    throw new ConfigError(lineNo, `${pathSoFar} is not a table`)
  }
  const t = { kind: 'table', map: new Map(), headerDefined: false }
  map.set(segment, t)
  return t
}

