    const nameRes = parseDottedName(line, pos, lineNo)
    pos = skipWS(line, nameRes.pos)
    if (line[pos] !== '=') {
      throw new ConfigError(lineNo, 'expected = in an inline table')
    }
    pos++
    const valRes = parseValue(line, pos, lineNo)
    assignInto(tableNode, nameRes.segments, valRes.node, lineNo)
    pos = skipWS(line, valRes.pos)
    if (pos >= line.length) throw new ConfigError(lineNo, 'unterminated inline table')
    const c = line[pos]
    if (c === '#' || c === ';') throw new ConfigError(lineNo, 'unterminated inline table')
    if (c === ',') {
      pos++
      pos = skipWS(line, pos)
      continue
    }
    if (c === '}') {
      return { node: tableNode, pos: pos + 1 }
    }
    throw new ConfigError(lineNo, 'unterminated inline table')
  }
}
