  return Array.from(map.keys()).sort(codePointCompare)
}

function typeName(node) {
  switch (node.kind) {
    case 'table':
      return 'table'
    case 'array':
    case 'arrayOfTables':
      return 'array'
    default:
      return node.kind
  }
