      return '{\n' + parts.join(',\n') + '\n' + pad + '}'
    }
    case 'array':
    case 'arrayOfTables': {
      const items = node.kind === 'array' ? node.items : node.items
      if (items.length === 0) return '[]'
      const parts = items.map((it) => padChild + serializeNode(it, depth + 1))
