      return JSON.stringify(node.value)
    case 'boolean':
      return node.value ? 'true' : 'false'
    case 'integer':
      return node.text
    case 'float':
      return JSON.stringify(node.value)
    default:
      throw new Error(`unknown node kind ${node.kind}`)
  }
}

export function toJson(root) {
  return serializeNode(root, 0) + '\n'
}

