  if (node.kind === 'table') {
    for (const k of sortedKeys(node.map)) {
      const child = node.map.get(k)
      const childPath = path === '' ? k : `${path}.${k}`
      out.push(`${childPath} ${typeName(child)}`)
      visitChildren(child, childPath, out)
    }
