/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import { readFileSync } from 'node:fs'
import { ConfigError } from './errors.js'
import { parseDocument } from './parser.js'
import { toJson, toKeys } from './serialize.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    fail('usage: cli.js json|keys')
    return
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e instanceof ConfigError) {
      fail(`line ${e.line}: ${e.reason}`)
      return
    }
    throw e
  }

  const out = mode === 'json' ? toJson(root) : toKeys(root)
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

